{
  "name": "@enowdev/mnemosyne",
  "version": "0.1.1",
  "description": "Combined OpenCode plugin: command filtering (RTK) + context pruning (DCP) + persistent memory + auto code indexing",
  "main": "dist/index.js",
  "module": "dist/index.js",
  "type": "module",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "mnemosyne.schema.json"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target bun",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "context-pruning",
    "token-optimization",
    "memory",
    "code-indexing",
    "llm",
    "ai"
  ],
  "author": "enowdev",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/enowdev/mnemosyne"
  },
  "devDependencies": {
    "@types/bun": "latest"
  },
  "peerDependencies": {
    "typescript": "^5"
  },
  "dependencies": {
    "@anthropic-ai/tokenizer": "^0.0.4",
    "@opencode-ai/plugin": "^1.2.25",
    "@opencode-ai/sdk": "^1.2.25",
    "fuzzball": "^2.2.3",
    "jsonc-parser": "^3.3.1",
    "yaml": "^2.8.2",
    "zod": "^4.3.6"
  }
}
